/*
 * ============================================================
 * TREE PREDICTION
 * ============================================================
 */

static float gb_predict_tree(
    uint32_t tree_index,
    const float *features
)
{
    uint32_t node;
    uint32_t offset;
    uint32_t node_count;

    offset = gb_tree_offset[tree_index];
    node_count = gb_tree_node_count[tree_index];

    /*
     * Root node is always node 0 inside this tree.
     */

    node = 0;

    while (1)
    {
        uint32_t global_node;
        int8_t feature_index;

        global_node = offset + node;

        feature_index = gb_feature[global_node];

        /*
         * Leaf node
         */

        if (feature_index < 0)
        {
            return gb_value[global_node];
        }

        /*
         * Safety check.
         */

        if (node >= node_count)
        {
            return 0.0f;
        }

        /*
         * Follow tree branch.
         */

        if (features[feature_index] <=
            gb_threshold[global_node])
        {
            node = (uint32_t)gb_left[global_node];
        }
        else
        {
            node = (uint32_t)gb_right[global_node];
        }
    }
}

/*
 * ============================================================
 * MAIN MODEL PREDICTION
 * ============================================================
 */

int oil_quality_predict(
    float temperature,
    float humidity,
    float tcs_r,
    float tcs_g,
    float tcs_b,
    float impedance
)
{
    float features[6];

    float raw_prediction[GB_NUM_CLASSES];

    uint32_t tree_index;

    uint32_t class_index;

    int best_class;

    float best_value;

    /*
     * --------------------------------------------------------
     * Feature vector
     * --------------------------------------------------------
     */

    features[0] = temperature;
    features[1] = humidity;
    features[2] = tcs_r;
    features[3] = tcs_g;
    features[4] = tcs_b;
    features[5] = impedance;

    /*
     * --------------------------------------------------------
     * Initialize with sklearn's initial prediction.
     * --------------------------------------------------------
     */

    for (class_index = 0;
         class_index < GB_NUM_CLASSES;
         class_index++)
    {
        raw_prediction[class_index] =
            gb_initial_prediction[class_index];
    }

    /*
     * --------------------------------------------------------
     * Add every boosting tree.
     *
     * sklearn multiclass GradientBoostingClassifier:
     *
     *   raw_prediction[class] +=
     *       learning_rate * tree_prediction
     *
     * --------------------------------------------------------
     */

    for (tree_index = 0;
         tree_index < GB_NUM_TREES;
         tree_index++)
    {
        class_index = gb_tree_class[tree_index];

        raw_prediction[class_index] +=
            gb_learning_rate *
            gb_predict_tree(
                tree_index,
                features
            );
    }

    /*
     * --------------------------------------------------------
     * Select class with highest raw prediction.
     * --------------------------------------------------------
     */

    best_class = 0;

    best_value = raw_prediction[0];

    for (class_index = 1;
         class_index < GB_NUM_CLASSES;
         class_index++)
    {
        if (raw_prediction[class_index] > best_value)
        {
            best_value = raw_prediction[class_index];

            best_class = (int)class_index;
        }
    }

    return best_class;
}
